function fibonacci()
    return coroutine.wrap(function()
        local a, b = 0, 1
        while true do
            coroutine.yield(a)
            a, b = b, a + b
        end
    end)
end

function take(gen, n)
    local out = {}
    for i = 1, n do out[i] = gen() end
    return out
end

function chunks(list, size)
    return coroutine.wrap(function()
        for start = 1, #list, size do
            local chunk = {}
            for i = start, math.min(start + size - 1, #list) do chunk[#chunk + 1] = list[i] end
            coroutine.yield(chunk)
        end
    end)
end

function interleave(...)
    local lists = { ... }
    return coroutine.wrap(function()
        local longest = 0
        for _, l in ipairs(lists) do longest = math.max(longest, #l) end
        for i = 1, longest do
            for _, l in ipairs(lists) do
                if l[i] ~= nil then coroutine.yield(l[i]) end
            end
        end
    end)
end
